    81	static int ssh_message_reply_default(ssh_message msg) {
    82	  SSH_LOG(SSH_LOG_FUNCTIONS, "Reporting unknown packet");
    83	
    84	  if (ssh_buffer_add_u8(msg->session->out_buffer, SSH2_MSG_UNIMPLEMENTED) < 0)
